1	import { NextRequest, NextResponse } from "next/server";
2	import { stripe, stripeConfigured } from "@/lib/stripe";
3	import { fulfilCheckoutSession } from "@/lib/fulfil-checkout";
4	import { releaseReservation } from "@/lib/promo-redemption";
5	import { releaseOrderCouponReservation } from "@/lib/coupon-redemption";
6	import { handleFailedPaymentIntent } from "@/lib/payment-failed-recovery";
7	import type Stripe from "stripe";
8	
9	export async function POST(req: NextRequest) {
10	  if (!stripeConfigured() || !process.env.STRIPE_WEBHOOK_SECRET) {
11	    return NextResponse.json({ error: "not configured" }, { status: 400 });
12	  }
13	  const sig = req.headers.get("stripe-signature");
14	  if (!sig) return NextResponse.json({ error: "missing signature" }, { status: 400 });
15	  const raw = await req.text();
16	
17	  let event;
18	  try {
19	    event = stripe().webhooks.constructEvent(raw, sig, process.env.STRIPE_WEBHOOK_SECRET);
20	  } catch {
21	    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
22	  }
23	
24	  // `async_payment_succeeded` is how a DELAYED local payment method (PayNow,
25	  // GrabPay, UPI, ...) reports that the money finally arrived: its
26	  // `checkout.session.completed` can fire while the session is still unpaid, which
27	  // fulfilCheckoutSession correctly treats as "not yet". Same idempotent call.
28	  // (Owner action: enable this event on the Stripe webhook endpoint before turning
29	  // any local method on — see docs/DOCUMENTATION.md, Local payment methods.)
30	  if (event.type === "checkout.session.completed" || event.type === "checkout.session.async_payment_succeeded") {
31	    const session = event.data.object as { id: string };
32	    // FULFIL, don't just credit. This used to call `creditCheckoutSession` and
33	    // throw the result away, which meant the webhook credited the wallet and then
34	    // — by winning the race — caused the success-redirect to see `credited: false`
35	    // and skip provisioning entirely. The webhook is the reliable signal (the
36	    // redirect may never happen at all), so it must be able to fulfil on its own.
37	    // `fulfilCheckoutSession` is idempotent via UNIQUE(FulfilledSession), so the
38	    // two callers racing is safe: exactly one does the work.
39	    //
40	    // Errors are swallowed deliberately — returning non-2xx makes Stripe retry the
41	    // event, and the failure is already recorded on the FulfilledSession row and
42	    // surfaced to the customer.
43	    try {
44	      await fulfilCheckoutSession(session.id);
45	    } catch (e) {
46	      console.error("[stripe-webhook] fulfil failed", session.id, e);
47	    }
48	  }
49	
50	  // A checkout the customer never completed: Stripe expires it (we cap the payable
51	  // window at ORDER_CHECKOUT_EXPIRES_MS). RELEASE any first-month-free hold it carried
52	  // so the customer's one-time offer is returned promptly rather than waiting for the
53	  // worker sweep. Guarded to RESERVED, so a completed+confirmed grant is never revoked.
54	  // (If this event type isn't enabled in the Stripe dashboard, the worker sweep is the
55	  // backstop — the hold's reservedUntil has passed by the time the session expires.)
56	  // A DELAYED local method (PayNow, GrabPay, UPI, ...) that the bank finally refused: the session is
57	  // complete but will never be paid, so it never expires either. Same release as an expiry — the
58	  // order was never placed (fulfilment only runs on `paid`), only the holds are returned.
59	  if (event.type === "checkout.session.expired" || event.type === "checkout.session.async_payment_failed") {
60	    const session = event.data.object as Stripe.Checkout.Session;
61	    const token = session.metadata?.nxeonPromoReservation;
62	    if (token) {
63	      try {
64	        await releaseReservation(token);
65	      } catch (e) {
66	        console.error("[stripe-webhook] release reservation failed", token, e);
67	      }
68	    }
69	    // Same for a checkout-coupon hold — return its per-person slot AND its global-cap
70	    // slot (timesRedeemed decrement inside releaseOrderCouponReservation). Guarded to
71	    // RESERVED, so a completed+confirmed CONSUMED redemption is never revoked.
72	    const couponToken = session.metadata?.nxeonCouponReservation;
73	    if (couponToken) {
74	      try {
75	        await releaseOrderCouponReservation(couponToken);
76	      } catch (e) {
77	        console.error("[stripe-webhook] release coupon reservation failed", couponToken, e);
78	      }
79	    }
80	  }
81	
82	  // A payment attempt failed. Filtered inside handleFailedPaymentIntent to only
83	  // act on the 3D Secure / authentication-stalled case — ordinary declines are
84	  // already shown to the customer inline by Stripe's own checkout UI. Errors
85	  // swallowed deliberately: a recovery-email hiccup must never surface as a
86	  // webhook failure Stripe would retry indefinitely.
87	  if (event.type === "payment_intent.payment_failed") {
88	    const pi = event.data.object as Stripe.PaymentIntent;
89	    try {
90	      await handleFailedPaymentIntent(pi);
91	    } catch (e) {
92	      console.error("[stripe-webhook] failed-payment recovery failed", pi.id, e);
93	    }
94	  }
95	
96	  return NextResponse.json({ received: true });
97	}
