1	import { NextRequest, NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { stripeConfigured, createTopUpPaymentSession, createLocalTopUpPaymentSession } from "@/lib/stripe";
4	import { isLocalMethodId, LOCAL_METHODS, localChargeCents } from "@/lib/local-payment-methods";
5	import { localPaymentConfig, isLocalMethodEnabled } from "@/lib/local-payments";
6	import { getSettingInt } from "@/lib/settings";
7	
8	/** Set by `components/customer/CouponField`; read by `topUp`'s demo gateway only. */
9	const COUPON_COOKIE = "nxeon_coupon";
10	
11	export async function POST(req: NextRequest) {
12	  const user = await currentUser();
13	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
14	  if (!stripeConfigured()) {
15	    return NextResponse.json({ error: "Stripe is not configured yet" }, { status: 400 });
16	  }
17	  const { amount, method } = await req.json().catch(() => ({}));
18	  const dollars = Number(amount);
19	  if (!Number.isFinite(dollars) || dollars > 5000) {
20	    return NextResponse.json({ error: "Amount must be $5–$5000" }, { status: 400 });
21	  }
22	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
23	  const minTopup = await getSettingInt("min_topup_cents", 500);
24	  if (Math.round(dollars * 100) < minTopup) {
25	    return NextResponse.json(
26	      { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}` },
27	      { status: 400 },
28	    );
29	  }
30	
31	  // A promo code must never be silently dropped at the moment money moves.
32	  //
33	  // `CouponField` stores an accepted code in this cookie for an hour, and the ONLY
34	  // reader is the demo gateway in `topUp`. This route charges the card and
35	  // `creditCheckoutSession` credits `session.amount_total` verbatim, so a bonus
36	  // simply cannot be added here — and Stripe's own `discounts` /
37	  // `allow_promotion_codes` are the wrong instrument for a wallet top-up: they
38	  // reduce `amount_total`, which reduces the credit by the same cents, leaving the
39	  // customer exactly where they started. So a cookie surviving into this path
40	  // (e.g. Stripe was configured after the code was accepted) would mean paying
41	  // full price with a code the UI said was applied — the audit's finding #8.
42	  //
43	  // Refuse, say why, and clear the cookie in the same response so the immediate
44	  // retry succeeds. Nothing has been charged at this point: no session exists yet.
45	  const staleCoupon = req.cookies.get(COUPON_COOKIE)?.value?.trim();
46	  if (staleCoupon) {
47	    const shown = staleCoupon.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32).toUpperCase();
48	    const res = NextResponse.json(
49	      {
50	        error: `Promo code ${shown || "on this account"} can’t be applied to a card payment. We’ve removed it — press Add funds again to continue without it.`,
51	      },
52	      { status: 400 },
53	    );
54	    res.cookies.set({ name: COUPON_COOKIE, value: "", path: "/", maxAge: 0 });
55	    return res;
56	  }
57	
58	  // A local payment method (PayNow, GrabPay, UPI, Alipay, WeChat Pay) — wallet
59	  // top-up only, default-off, see lib/local-payment-methods.ts. `method` absent or
60	  // "card" is the unchanged card path below. An unknown or not-enabled method is
61	  // REFUSED, never silently turned into a card session.
62	  if (method !== undefined && method !== "card") {
63	    if (!isLocalMethodId(method) || !(await isLocalMethodEnabled(method))) {
64	      return NextResponse.json({ error: "That payment method isn’t available right now." }, { status: 400 });
65	    }
66	    const usdCents = Math.round(dollars * 100);
67	    const cfg = await localPaymentConfig();
68	    let local = null;
69	    try {
70	      local = await createLocalTopUpPaymentSession(user, usdCents, method, cfg);
71	    } catch (e) {
72	      // Stripe refusing the method/currency for this account lands here — nothing was charged.
73	      console.error("[stripe-checkout] local method session failed", method, e instanceof Error ? e.message : e);
74	    }
75	    return NextResponse.json(
76	      local ? { clientSecret: local.clientSecret, publishableKey: local.publishableKey, method, charge: { currency: LOCAL_METHODS[method].chargeCurrency, cents: localChargeCents({ usdCents, method, rates: cfg.rates, bufferPct: cfg.bufferPct }) } } : { error: "We couldn’t start that payment method. Please try another or pay by card." },
77	      local ? undefined : { status: 502 },
78	    );
79	  }
80	
81	  // Custom Checkout (ui_mode: "elements") — the SAME session shape/UI mode the
82	  // VPS/Hosting/Game/Email deploy wizards' Payment step uses (PaymentStep.tsx),
83	  // mounted here in AddFundsPaymentModal instead of Stripe's own hosted-style
84	  // embedded page. `createTopUpPaymentSession` attaches the payment to a Stripe
85	  // CUSTOMER and saves the card (off-session renewals) exactly as before — see
86	  // its doc comment in lib/stripe.ts for why the session carries no order/game/
87	  // host/email metadata key (it must classify as a plain top-up).
88	  const session = await createTopUpPaymentSession(user, Math.round(dollars * 100));
89	  return NextResponse.json(
90	    session ? { clientSecret: session.clientSecret, publishableKey: session.publishableKey } : { error: "Stripe didn't return a session. Please try again." },
91	    session ? undefined : { status: 502 },
92	  );
93	}
