1063	/**
1064	 * Wallet top-up through a Stripe LOCAL payment method (PayNow, GrabPay, UPI,
1065	 * Alipay, WeChat Pay) — see lib/local-payment-methods.ts for why these are
1066	 * wallet-only and how the charge currency works. DEFAULT-OFF: callers
1067	 * (app/api/stripe/checkout) only reach this after `isLocalMethodEnabled`.
1068	 *
1069	 * Differs from `createTopUpPaymentSession` deliberately:
1070	 *   - exactly one payment method type, never "card";
1071	 *   - NO `setup_future_usage` / `saved_payment_method_options` — local methods
1072	 *     cannot be saved for off-session charges and Stripe rejects the combination;
1073	 *   - the line item is in the method's own currency (SGD/INR need an admin FX rate;
1074	 *     refused here with `null` if there is none), and the USD amount the wallet
1075	 *     will receive rides in metadata (`nxeonCreditUsdCents`) for
1076	 *     `walletCreditCents` — the customer is never credited the foreign-currency
1077	 *     cents as if they were dollars.
1078	 * Carries `nxeonUserId` and no order key, so it classifies as a plain top-up.
1079	 * Returns null when it cannot be priced or Stripe returns no client secret.
1080	 */
1081	export async function createLocalTopUpPaymentSession(
1082	  user: CardUser,
1083	  usdCents: number,
1084	  method: LocalMethodId,
1085	  cfg: { rates: Record<string, number>; bufferPct: number },
1086	): Promise<CustomCheckout | null> {
1087	  if (!stripeConfigured() || usdCents <= 0) return null;
1088	  const m = LOCAL_METHODS[method];
1089	  const chargeCents = localChargeCents({ usdCents, method, rates: cfg.rates, bufferPct: cfg.bufferPct });
1090	  if (chargeCents === null) return null;
1091	  const base = process.env.APP_URL ?? "http://localhost:3000";
1092	  const { ensureStripeCustomer } = await import("./stripe-cards");
1093	  const customerId = await ensureStripeCustomer(user);
1094	  const session = await stripe().checkout.sessions.create(
1095	    {
1096	      mode: "payment",
1097	      customer: customerId,
1098	      payment_method_types: [m.stripeType as Stripe.Checkout.SessionCreateParams.PaymentMethodType],
1099	      expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
1100	      line_items: [
1101	        {
1102	          price_data: { currency: m.chargeCurrency.toLowerCase(), product_data: { name: "Nxeon wallet credit" }, unit_amount: chargeCents },
1103	          quantity: 1,
1104	        },
1105	      ],
1106	      metadata: {
1107	        nxeonUserId: user.id,
1108	        nxeonLocalPay: method,
1109	        nxeonCreditUsdCents: String(usdCents),
1110	      },
1111	      ui_mode: CUSTOM_CHECKOUT_UI_MODE,
1112	      return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
1113	    },
1114	    EMBEDDED_REQUEST_OPTS,
1115	  );
1116	  return session.client_secret ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : null;
1117	}
1118	
1119	/**
1120	 * Deploy-wizard ORDER paid through a Stripe local payment method. The session
1121	 * carries the same nxeon* order metadata a card session carries (so it classifies
1122	 * as that order and is fulfilled by the one audited path), plus `nxeonLocalPay` and
1123	 * the USD credit. It is charged in the method's currency, credits the wallet exactly
1124	 * the USD card leg (`walletCreditCents`), and the order is then placed from the
1125	 * wallet. Rules and refusals live in the pure `buildLocalOrderSession`
1126	 * (lib/local-order-payment.ts). No `setup_future_usage`: a local method cannot be
1127	 * saved, so this order's renewals draw from the wallet. Returns null when it cannot
1128	 * be built or Stripe returns no client secret. Never places the order itself.
1129	 */
1130	export async function createLocalOrderPaymentSession(
1131	  user: CardUser,
1132	  usdCents: number,
1133	  method: LocalMethodId,
1134	  cfg: { rates: Record<string, number>; bufferPct: number },
1135	  quoteMetadata: Record<string, string>,
1136	  productName: string,
1137	): Promise<(CustomCheckout & { chargeCurrency: string; chargeCents: number }) | null> {
1138	  if (!stripeConfigured()) return null;
1139	  const { buildLocalOrderSession } = await import("./local-order-payment");
1140	  const body = buildLocalOrderSession({
1141	    userId: user.id, method, usdCents, rates: cfg.rates, bufferPct: cfg.bufferPct, quoteMetadata, productName,
1142	  });
1143	  if ("error" in body) return null;
1144	  const base = process.env.APP_URL ?? "http://localhost:3000";
1145	  const { ensureStripeCustomer } = await import("./stripe-cards");
1146	  const customerId = await ensureStripeCustomer(user);
1147	  const session = await stripe().checkout.sessions.create(
1148	    {
1149	      mode: "payment",
1150	      customer: customerId,
1151	      payment_method_types: [body.stripeType as Stripe.Checkout.SessionCreateParams.PaymentMethodType],
1152	      expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
1153	      line_items: [
1154	        { price_data: { currency: body.currency, product_data: { name: body.productName }, unit_amount: body.unitAmount }, quantity: 1 },
1155	      ],
1156	      metadata: body.metadata,
1157	      ui_mode: CUSTOM_CHECKOUT_UI_MODE,
1158	      return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
1159	    },
1160	    EMBEDDED_REQUEST_OPTS,
1161	  );
1162	  return session.client_secret
1163	    ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey(), chargeCurrency: body.currency.toUpperCase(), chargeCents: body.unitAmount }
1164	    : null;
1165	}
1166	
1167	/**
1168	 * A cents amount that arrived from OUTSIDE this process (Stripe metadata) and is
1169	 * about to be handed to `debitWallet`. Integer, non-negative, finite — anything

1515	 * Called from both the success-redirect confirm route (works without HTTPS)
1516	 * and the webhook (belt-and-suspenders once HTTPS is available).
1517	 * Returns true if a credit was applied this call.
1518	 *
1519	 * Takes the ALREADY-RETRIEVED session rather than an id: `fulfilCheckoutSession`
1520	 * fetches it once and both the credit and the fulfilment routing read that single
1521	 * object, so the two can never disagree about what this payment was (and a Stripe
1522	 * read failure surfaces in one place, loudly, instead of four times as `null`).
1523	 */
1524	export async function creditCheckoutSession(session: Stripe.Checkout.Session): Promise<boolean> {
1525	  const userId = session.metadata?.nxeonUserId;
1526	  // USD cents to credit. For an ordinary (USD) session this is `amount_total`
1527	  // exactly as before; a local-payment-method session is charged in SGD/INR, so
1528	  // its credit comes from the USD amount it was priced for (see walletCreditCents).
1529	  const cents = walletCreditCents(session);
1530	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
1531	
1532	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
1533	  // session id inside the description.
1534	  const legacy = await db.walletTransaction.findFirst({
1535	    where: { stripeSessionId: null, description: { contains: session.id } },
1536	  });
1537	  if (legacy) return false;
1538	
1539	  // Is this credit a product the customer bought, or the funding leg of something
1540	  // else they bought? Only the first is a "Wallet top-up" and only the first gets
1541	  // a billing document — see isPurchaseLegSession for the incident.
1542	  const purchaseLeg = isPurchaseLegSession(session.metadata);
1543	
1544	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
1545	  // read-then-write check. The confirm-redirect and the webhook can arrive
1546	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
1547	  // only the database can safely decide the winner. P2002 == already credited.
1548	  const ops: Prisma.PrismaPromise<unknown>[] = [
1549	    db.walletTransaction.create({
1550	      data: {
1551	        userId,
1552	        amountCents: cents,
1553	        description: `Stripe payment (${session.id})`,
1554	        stripeSessionId: session.id,
1555	      },
1556	    }),
1557	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
1558	    db.notification.create({
1559	      data: {
1560	        userId,
1561	        title: `Payment of $${(cents / 100).toFixed(2)} received`,
1562	        href: "/dashboard/billing",
1563	      },
1564	    }),
1565	  ];
1566	  // Index of the invoice-create inside `ops`, or -1 when no invoice is issued
1567	  // (a purchase leg). Used to recover the new invoice's id for the receipt email.
1568	  let invoiceOpIndex = -1;
1569	  if (!purchaseLeg) {
1570	    // PAID invoice for the top-up. Created in the SAME guarded transaction as
1571	    // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
1572	    // the credit idempotent also prevents a duplicate invoice on replay.
1573	    //
1574	    // A purchase leg is deliberately left undocumented HERE: the order, resize or
1575	    // disk-expansion it funds issues the one invoice for the whole purchase, and
1576	    // that document — not this one — is what the customer's card statement shows.
1577	    // If the fulfilment then fails the money stays in the wallet as an ordinary
1578	    // credit (ledger row + notification), and the invoice is issued by whatever it
1579	    // is eventually spent on; inventing a top-up document at that point would
1580	    // double-count the same dollars all over again the moment they deploy.
1581	    // Remember WHERE in the batch this lands, so the created row's id can be read
1582	    // back out of the transaction result. The receipt email promises the customer
1583	    // an attached invoice, and it can only keep that promise if it knows the id.
1584	    invoiceOpIndex = ops.length;
1585	    ops.push(
1586	      db.invoice.create({
1587	        data: invoiceCreateData({
1588	          userId,
1589	          description: "Wallet top-up",
1590	          status: "PAID",
1591	          lineItems: [
1592	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
1593	          ],
1594	        }),
1595	      }),
1596	    );
1597	  }
1598	  let invoiceId: string | undefined;
1599	  try {
1600	    const results = await db.$transaction(ops);
1601	    if (invoiceOpIndex >= 0) {
1602	      const created = results[invoiceOpIndex] as { id?: string } | undefined;
1603	      invoiceId = created?.id;
1604	    }
1605	  } catch (e) {
1606	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
1607	    throw e;
1608	  }
1609	  // A funded wallet is the referred user's first paid action — reward both sides.
1610	  try {
1611	    const { maybeRewardReferral } = await import("./actions-growth");
1612	    await maybeRewardReferral(userId);
1613	  } catch { /* best-effort */ }
1614	  try {
1615	    // On a purchase leg, skip this generic receipt entirely: the order this
1616	    // credit is funding (VPS/hosting/email/game) issues its OWN specific,
1617	    // itemised invoice_new email moments later (the same one fixed today to
1618	    // correctly say "paid" rather than "due"), and it names the actual plan/
1619	    // domain/hostname the money bought. Sending BOTH meant every purchase-
1620	    // funding payment produced two emails: a generic, invoice-less "Payment
1621	    // received — your Nxeon order" (real customer feedback: "this email is
1622	    // weak") immediately followed by the real invoice — pure noise. A genuine
1623	    // standalone top-up (not funding a specific purchase) still gets this
1624	    // receipt, since nothing else will ever tell the customer their wallet
1625	    // balance grew.
1626	    if (!purchaseLeg) {
1627	      const u = await db.user.findUnique({ where: { id: userId } });
1628	      if (u) {
1629	        const { sendMail, emails } = await import("./mailer");
1630	        const tpl = emails.receipt(
1631	          `$${(cents / 100).toFixed(2)}`,
1632	          "wallet top-up",
1633	          !!invoiceId,
1634	        );
