199	export async function captureExternalPayPalOrder(
200	  paypalOrderId: string,
201	  pendingId: string,
202	): Promise<{ redirect?: string; error?: string }> {
203	  const user = await requireUser();
204	  const row = await db.pendingExternalPayment.findUnique({ where: { id: pendingId } });
205	  if (!row || row.userId !== user.id || row.provider !== "paypal") {
206	    return { error: "We couldn't find that payment." };
207	  }
208	
209	  let captured;
210	  try {
211	    captured = await capturePayPalOrder(paypalOrderId);
212	  } catch (e) {
213	    console.error("[payments] PayPal capture failed", paypalOrderId, e);
214	    return { error: "We couldn't confirm that PayPal payment. If you were charged, contact support — your money is safe." };
215	  }
216	  if (captured.status !== "COMPLETED") {
217	    return { error: `PayPal reported this payment as "${captured.status}" — please try again or use another method.` };
218	  }
219	  // Defence in depth: the captured amount must match what we asked PayPal to
220	  // charge. It always will (we set it), but a mismatch here means something is
221	  // wrong enough that fulfilling on trust would be the bug, not the fix.
222	  const capturedCents = Math.round(
223	    Number(captured.purchase_units?.[0]?.payments?.captures?.[0]?.amount?.value ?? "0") * 100,
224	  );
225	  if (capturedCents !== row.amountCents) {
226	    console.error("[payments] PayPal captured amount mismatch", { paypalOrderId, capturedCents, expected: row.amountCents });
227	    return { error: "That payment didn't match the expected amount. Contact support — nothing has been provisioned." };
228	  }
229	
230	  // Best-effort, mirrors saveCardFromPaymentSession (lib/stripe-cards.ts): the
231	  // money has already been confirmed above, so a failure here must be inert
232	  // and never turn a successful payment into a reported error.
233	  const vault = vaultInfoFromCapture(captured);
234	  if (vault) {
235	    try {
236	      await db.user.update({
237	        where: { id: user.id },
238	        data: { paypalVaultId: vault.vaultId, paypalPayerEmail: vault.payerEmail },
239	      });
240	    } catch (e) {
241	      console.error("[payments] could not record vaulted PayPal method", e);
242	    }
243	  }
244	
245	  try {
246	    const result: FulfilResult = await fulfilExternalPayment({
247	      provider: "paypal",
248	      externalId: paypalOrderId,
249	      pendingId,
250	      base: appBase(),
251	    });
252	    return { redirect: result.redirect };
253	  } catch (e) {
254	    console.error("[payments] PayPal fulfilment failed", paypalOrderId, e);
255	    return { error: "Your PayPal payment went through but we couldn't finish setup. Contact support — your money is safe and we've been alerted." };
256	  }
257	}
