1	/**
2	 * Stripe LOCAL payment methods (PayNow, GrabPay, UPI, Alipay, WeChat Pay) for
3	 * wallet top-ups. PURE — no db, no settings, no Stripe client — so the rules are
4	 * unit-testable and safe to import from client components. The DB-backed half
5	 * (which methods are switched on right now) is lib/local-payments.ts.
6	 *
7	 * WHY WALLET TOP-UPS ONLY. Every local method here is a one-time, customer-present
8	 * payment: none can be saved and charged off-session the way a card can, and the
9	 * platform's renewals draw from a saved card or the wallet. So a local method is
10	 * offered where money lands in the WALLET (Add funds), and the wallet then pays
11	 * the order or the renewal. They are deliberately NOT offered as a way to pay an
12	 * order directly, which would break auto-renewal and the purchase-leg fulfilment
13	 * (lib/stripe.ts `isPurchaseLegSession`) that assumes a card/wallet funding leg.
14	 *
15	 * WHICH METHODS ARE REAL FOR US. A method is only available to a merchant whose
16	 * Stripe account is registered in a supporting country. The source for the table
17	 * below is Stripe's payment-method support table as read into the growth backlog
18	 * on 2026-10-01 (mkt-016): PayNow is Singapore merchants only; GrabPay is
19	 * Malaysia/Singapore; UPI includes Canada and Singapore; Alipay and WeChat Pay
20	 * are offered to Canadian accounts. Our Stripe entity's country is NOT verified
21	 * in the repo (it is read from the `stripe_account_country` setting, blank by
22	 * default), so with no country set NO local method is offered. Not offered:
23	 * GCash and QRIS (no native Stripe support for an SG account, no local PSP is
24	 * integrated) and FPX/PromptPay (we do not hold a MY/TH entity).
25	 *
26	 * CHARGE CURRENCY. PayNow and GrabPay can only be charged in SGD, UPI in INR.
27	 * Nothing in the repo supplies a trustworthy FX rate (lib/currency.ts's table is
28	 * documented as a coarse display snapshot), so a non-USD method is unavailable
29	 * until an admin enters a rate for that currency (`local_pay_fx_rates`). The
30	 * customer is charged `usd x rate x (1 + buffer)` rounded UP; the wallet is
31	 * credited exactly the USD amount they asked for. Alipay and WeChat Pay are
32	 * requested in USD (both support it per Stripe's currency table) so they need no
33	 * rate; if Stripe refuses that for the account, session creation fails cleanly
34	 * and the customer sees the error — nothing is charged.
35	 */
36	
37	export type LocalMethodId = "paynow" | "grabpay" | "upi" | "alipay" | "wechat_pay";
38	
39	export type LocalMethod = {
40	  id: LocalMethodId;
41	  /** Stripe `payment_method_types` value. */
42	  stripeType: string;
43	  label: string;
44	  /** Currency Stripe will charge the customer in (ISO 4217, upper case). */
45	  chargeCurrency: string;
46	  /** Stripe-account countries that can accept this method. */
47	  entityCountries: readonly string[];
48	  /** Customer countries this method is for (landing-page display + suggestion order). */
49	  customerCountries: readonly string[];
50	  /** One honest line for the picker. */
51	  note: string;
52	};
53	
54	export const LOCAL_METHODS: Record<LocalMethodId, LocalMethod> = {
55	  paynow: {
56	    id: "paynow", stripeType: "paynow", label: "PayNow", chargeCurrency: "SGD",
57	    entityCountries: ["SG"], customerCountries: ["SG"],
58	    note: "Scan the QR code in your banking app. Charged in Singapore dollars.",
59	  },
60	  grabpay: {
61	    id: "grabpay", stripeType: "grabpay", label: "GrabPay", chargeCurrency: "SGD",
62	    entityCountries: ["SG"], customerCountries: ["SG", "MY"],
63	    note: "Pay from your Grab wallet. Charged in Singapore dollars.",
64	  },
65	  upi: {
66	    id: "upi", stripeType: "upi", label: "UPI", chargeCurrency: "INR",
67	    entityCountries: ["SG", "CA"], customerCountries: ["IN"],
68	    note: "Pay with any UPI app. Charged in Indian rupees.",
69	  },
70	  alipay: {
71	    id: "alipay", stripeType: "alipay", label: "Alipay", chargeCurrency: "USD",
72	    entityCountries: ["CA"], customerCountries: ["CN", "HK", "MY", "SG"],
73	    note: "Pay with the Alipay app.",
74	  },
75	  wechat_pay: {
76	    id: "wechat_pay", stripeType: "wechat_pay", label: "WeChat Pay", chargeCurrency: "USD",
77	    entityCountries: ["CA"], customerCountries: ["CN", "HK", "SG"],
78	    note: "Pay with the WeChat app.",
79	  },
