82	export const LOCAL_METHOD_IDS = Object.keys(LOCAL_METHODS) as LocalMethodId[];
83	
84	export function isLocalMethodId(v: unknown): v is LocalMethodId {
85	  return typeof v === "string" && Object.prototype.hasOwnProperty.call(LOCAL_METHODS, v);
86	}
