88	/** Setting key holding a method's on/off flag (default "false" — see lib/settings.ts). */
89	export const localMethodFlagKey = (id: LocalMethodId) => `pay_method_${id}`;
90	
91	/** True when a Stripe account registered in `entityCountry` can take this method. */
92	export function methodSupportedByEntity(id: LocalMethodId, entityCountry: string | null | undefined): boolean {
93	  const c = (entityCountry ?? "").trim().toUpperCase();
94	  if (c.length !== 2) return false;
95	  return LOCAL_METHODS[id].entityCountries.includes(c);
96	}
