98	/**
99	 * Parse the `local_pay_fx_rates` setting: a JSON object of currency -> units of
100	 * that currency per 1 USD, e.g. {"SGD":1.3,"INR":83}. Anything malformed,
101	 * non-positive or non-finite is dropped, so a typo can only make a method
102	 * unavailable, never charge a wrong amount. USD is always 1.
103	 */
104	export function parseLocalFxRates(json: string | null | undefined): Record<string, number> {
105	  const out: Record<string, number> = { USD: 1 };
106	  if (!json) return out;
107	  try {
108	    const raw = JSON.parse(json);
109	    if (raw && typeof raw === "object" && !Array.isArray(raw)) {
110	      for (const [k, v] of Object.entries(raw as Record<string, unknown>)) {
111	        const code = k.trim().toUpperCase();
112	        const rate = typeof v === "number" ? v : Number(v);
113	        if (/^[A-Z]{3}$/.test(code) && code !== "USD" && Number.isFinite(rate) && rate > 0 && rate < 1_000_000) {
114	          out[code] = rate;
115	        }
116	      }
117	    }
118	  } catch { /* unreadable -> only USD */ }
119	  return out;
120	}
121	
122	/**
123	 * What to charge in the method's own currency for a wallet credit of `usdCents`.
124	 * `null` = cannot be priced (no admin rate for that currency). Rounded UP to the
125	 * smallest currency unit so FX rounding never leaves the wallet short-funded.
126	 * All supported currencies here are two-decimal (SGD, INR, USD).
127	 */
128	export function localChargeCents(opts: {
129	  usdCents: number;
130	  method: LocalMethodId;
131	  rates: Record<string, number>;
132	  bufferPct: number;
133	}): number | null {
134	  const { usdCents, method, rates } = opts;
135	  if (!Number.isInteger(usdCents) || usdCents <= 0) return null;
136	  const cur = LOCAL_METHODS[method].chargeCurrency;
137	  const rate = cur === "USD" ? 1 : rates[cur];
138	  if (!(typeof rate === "number" && rate > 0 && Number.isFinite(rate))) return null;
139	  const buffer = cur === "USD" ? 0 : Math.min(Math.max(Number.isFinite(opts.bufferPct) ? opts.bufferPct : 0, 0), 20);
140	  // Round to 6 dp before ceil so float noise (1.3 * 100 = 130.00000000000003) can't add a unit.
141	  const raw = Math.round(usdCents * rate * (1 + buffer / 100) * 1e6) / 1e6;
142	  return Math.ceil(raw);
143	}
144	
145	/**
146	 * The USD cents a PAID Checkout Session should add to the wallet.
147	 *
148	 * Before local methods every session was USD, so the credit was simply
149	 * `amount_total`. A non-USD session's `amount_total` is in a DIFFERENT currency's
150	 * cents, so crediting it verbatim would hand out e.g. 1.3x the money. A local
151	 * session therefore carries the USD credit it was priced for in its own metadata
152	 * (set server-side at creation, `nxeonCreditUsdCents`), and this function:
153	 *   - USD session, no local-method marker  -> `amount_total` (unchanged behaviour);
154	 *   - local-method session                 -> the metadata credit, but only if the
155	 *     method is known AND the session really was charged in that method's
156	 *     currency (a mismatched/tampered session credits nothing);
157	 *   - any other non-USD session            -> 0 (refuse rather than guess).
158	 */
159	export function walletCreditCents(session: {
160	  amount_total?: number | null;
161	  currency?: string | null;
162	  metadata?: Record<string, string> | null;
163	}): number {
164	  const total = session.amount_total ?? 0;
165	  const cur = (session.currency ?? "usd").toUpperCase();
166	  const marker = session.metadata?.nxeonLocalPay;
167	  if (!marker) return cur === "USD" && Number.isInteger(total) && total > 0 ? total : 0;
168	  if (!isLocalMethodId(marker)) return 0;
169	  if (cur !== LOCAL_METHODS[marker].chargeCurrency) return 0;
170	  const credit = Number(session.metadata?.nxeonCreditUsdCents);
171	  if (!Number.isInteger(credit) || credit <= 0) return 0;
172	  // A USD-charged local session must credit exactly what it charged.
173	  if (cur === "USD" && credit !== total) return 0;
174	  return credit;
175	}
