8	/**
9	 * Which Stripe local payment methods are REALLY offerable right now.
10	 *
11	 * A method is on only when ALL of these hold — each one is a way to avoid showing
12	 * (or letting through) a method that cannot take money:
13	 *   1. Stripe is configured;
14	 *   2. its per-method flag `pay_method_<id>` is true (default false);
15	 *   3. the Stripe account country (`stripe_account_country`, blank by default) is
16	 *      one Stripe supports the method for (lib/local-payment-methods.ts);
17	 *   4. it can be priced: USD methods always, SGD/INR methods only once an admin
18	 *      has entered an FX rate for that currency (`local_pay_fx_rates`).
19	 *
20	 * Server-only (reads settings). Never charges anything.
21	 */
22	export type EnabledLocalMethod = LocalMethod & { available: true };
23	
24	export async function localPaymentConfig() {
25	  const [country, ratesJson, bufferRaw] = await Promise.all([
26	    getSetting("stripe_account_country"),
27	    getSetting("local_pay_fx_rates"),
28	    getSetting("local_pay_fx_buffer_pct"),
29	  ]);
30	  const buffer = Number(bufferRaw);
31	  return {
32	    entityCountry: country.trim().toUpperCase(),
33	    rates: parseLocalFxRates(ratesJson),
34	    bufferPct: Number.isFinite(buffer) ? buffer : 2,
35	  };
36	}
37	
38	export async function enabledLocalMethods(): Promise<EnabledLocalMethod[]> {
39	  if (!stripeConfigured()) return [];
40	  const cfg = await localPaymentConfig();
41	  if (!cfg.entityCountry) return [];
42	  const out: EnabledLocalMethod[] = [];
43	  for (const id of LOCAL_METHOD_IDS) {
44	    if (!(await getSettingBool(localMethodFlagKey(id), false))) continue;
45	    if (!methodSupportedByEntity(id, cfg.entityCountry)) continue;
46	    // Pricing probe: 1 USD. null means no usable rate for this method's currency.
47	    if (localChargeCents({ usdCents: 100, method: id, rates: cfg.rates, bufferPct: cfg.bufferPct }) === null) continue;
48	    out.push({ ...LOCAL_METHODS[id], available: true });
49	  }
50	  return out;
51	}
