57	/**
58	 * Enabled local methods that are meant for visitors from `country` (ISO alpha-2,
59	 * any case). Empty for every country we have no real method for (PH, ID, VN ...) —
60	 * GCash/QRIS are NOT supported, so those pages simply say nothing.
61	 */
62	export async function localMethodsForCountry(country: string | null | undefined): Promise<EnabledLocalMethod[]> {
63	  const cc = (country ?? "").trim().toUpperCase();
64	  if (cc.length !== 2) return [];
65	  return (await enabledLocalMethods()).filter((m) => m.customerCountries.includes(cc));
66	}
