69	 * One marketing "stat card" (the landing templates' `au-card` markup) naming the
70	 * local methods enabled for this country, or "" when none are — so a landing page
71	 * can only ever advertise a method that checkout will actually accept. Values are
72	 * static strings from LOCAL_METHODS, never user input.
73	 */
74	export async function localPayCardHtml(country: string | null | undefined): Promise<string> {
75	  let methods: EnabledLocalMethod[] = [];
76	  try { methods = await localMethodsForCountry(country); } catch { return ""; }
77	  if (methods.length === 0) return "";
78	  const names = methods.map((m) => m.label);
