import {
  LOCAL_METHODS, isLocalMethodId, localChargeCents, walletCreditCents, type LocalMethodId,
} from "./local-payment-methods";

/**
 * Paying a deploy-wizard ORDER with a Stripe local payment method (PayNow, GrabPay,
 * UPI, Alipay, WeChat Pay). PURE — no db, no settings, no Stripe client — so the
 * money rules are unit-testable (test/local-order-payment.test.ts).
 *
 * THE DESIGN IN ONE PARAGRAPH. A local method cannot be saved for renewals and may
 * be charged in SGD/INR, and this repo cannot price a non-USD ORDER. So the order is
 * still priced, quoted, wallet-split and stamped in USD exactly as the card path does
 * (lib/actions-payment-providers.ts `quote*OrderForExternalPayment`), and the local
 * method only pays the USD CARD LEG into the wallet: a Stripe session whose metadata
 * carries the SAME nxeon* order keys a card session carries, plus the marker
 * `nxeonLocalPay` and the USD credit `nxeonCreditUsdCents`. Fulfilment is the one
 * audited path (`fulfilCheckoutSession`): it credits the wallet `walletCreditCents`
 * (exactly the USD card leg, never the SGD/INR cents) and then places the order from
 * the wallet at the price stamped before payment. Nothing is placed until Stripe says
 * `payment_status: "paid"` (async methods: `checkout.session.async_payment_succeeded`),
 * and the FulfilledSession claim makes duplicate webhooks a no-op.
 */

/** Wizard products a local method can pay for. Domains have no external-payment rail. */
export const LOCAL_ORDER_SERVICES = ["vps", "game", "hosting", "email"] as const;
export type LocalOrderService = (typeof LOCAL_ORDER_SERVICES)[number];

export function isLocalOrderService(v: unknown): v is LocalOrderService {
  return typeof v === "string" && (LOCAL_ORDER_SERVICES as readonly string[]).includes(v);
}

/** The metadata keys that make `classifyCheckoutSession` treat a session as an order. */
const ORDER_KEYS = ["nxeonOrder", "nxeonGameOrder", "nxeonHostOrder", "nxeonEmailOrder"] as const;

export type LocalOrderSessionBody = {
  stripeType: string;
  /** ISO 4217 lower case, as Stripe takes it. */
  currency: string;
  /** What Stripe charges, in the method's own currency's minor unit. */
  unitAmount: number;
  /** The USD cents the wallet receives once paid (equals the order's card leg). */
  creditUsdCents: number;
  metadata: Record<string, string>;
  productName: string;
};

/**
 * Build the Stripe session body for a local-method order payment, or `{ error }` when
 * it must not be built. Refuses (rather than guesses) on: an unknown method, a non-
 * positive/non-integer USD amount, a method that cannot be priced (no FX rate), quote
 * metadata that is not a plain order for this user, or metadata that already carries a
 * local-pay marker. The marker/credit keys are written LAST so nothing upstream can
 * override them.
 */
export function buildLocalOrderSession(opts: {
  userId: string;
  method: unknown;
  usdCents: number;
  rates: Record<string, number>;
  bufferPct: number;
  quoteMetadata: Record<string, string>;
  productName: string;
}): LocalOrderSessionBody | { error: string } {
  if (!isLocalMethodId(opts.method)) return { error: "Unknown payment method." };
  const method: LocalMethodId = opts.method;
  if (!Number.isInteger(opts.usdCents) || opts.usdCents <= 0) return { error: "Nothing to pay." };
  const md = opts.quoteMetadata;
  if (md.nxeonUserId !== opts.userId) return { error: "Order does not belong to this account." };
  if ("nxeonLocalPay" in md || "nxeonCreditUsdCents" in md) return { error: "Order metadata is already marked." };
  const present = ORDER_KEYS.filter((k) => typeof md[k] === "string" && md[k] !== "");
  if (present.length !== 1) return { error: "Order metadata is not a single order." };
  const charge = localChargeCents({ usdCents: opts.usdCents, method, rates: opts.rates, bufferPct: opts.bufferPct });
  if (charge === null) return { error: "That payment method can't be priced right now." };
  const m = LOCAL_METHODS[method];
  const metadata: Record<string, string> = {
    ...md,
    nxeonLocalPay: method,
    nxeonCreditUsdCents: String(opts.usdCents),
  };
  const body: LocalOrderSessionBody = {
    stripeType: m.stripeType,
    currency: m.chargeCurrency.toLowerCase(),
    unitAmount: charge,
    creditUsdCents: opts.usdCents,
    metadata,
    productName: opts.productName,
  };
  // Self-check: what fulfilment would credit for this exact session must equal the USD card
  // leg. If this ever disagrees something upstream changed and no session may be opened.
  const credit = walletCreditCents({ amount_total: charge, currency: m.chargeCurrency, metadata });
  if (credit !== opts.usdCents) return { error: "Internal pricing check failed." };
  return body;
}

/** Order-session marker test, shared by fulfilment (skip card-saving, report USD). */
export function isLocalOrderSession(metadata: Record<string, string> | null | undefined): boolean {
  return !!metadata?.nxeonLocalPay && ORDER_KEYS.some((k) => !!metadata[k]);
}

