        idempotencyKey: `nxeon_autorecharge_${user.id}_${day}_${amount}`,
        metadata: { nxeonKind: "auto_recharge" },
      });
    } catch (e) {
      // One wedged account must not stop the others from topping up.
      console.error(`[billing] auto-recharge error for ${user.email}`, e);
      continue;
    }

    if (result.ok) {
      const credited = await creditOffSessionCharge({
        userId: user.id,
        amountCents: result.amountCents,
        description: `${AUTO_RECHARGE_DESC} (${savedCardLabel(user) ?? "saved card"})`,
        paymentIntentId: result.paymentIntentId,
        // This charge IS the whole payment, so it gets its own PAID invoice — in
        // the same guarded write, so the invoice cannot outlive a rolled-back credit.
        invoiceDescription: AUTO_RECHARGE_DESC,
      });
      if (!credited) continue; // already credited today — nothing new to announce
      await mail(
        user.email,
        user.id,
        emails.paymentReceipt(fmtUsd(result.amountCents), AUTO_RECHARGE_DESC, user.cardLast4 ?? ""),
        "receipt", // ACCOUNT tier — suppressible; see the `mail()` default above.
      );
      await notify(
        user.id,
        `Wallet topped up ${fmtUsd(result.amountCents)}`,
        `Your balance had dropped below ${fmtUsd(threshold)}, so we topped it up automatically using your saved card.`,
        "/dashboard/billing",
      );
      console.log(`[billing] auto-recharged ${user.email} by ${fmtUsd(result.amountCents)}`);
      continue;
    }

    if (result.kind === "unavailable") {
      // The method is gone or dead at Stripe. Retire it so the portal stops
      // offering a card that cannot be charged (see attemptCardRenewal). Only
      // when the saved method ITSELF is the problem (`reason` present) — a bare
      // "unavailable" (floor/config) must not retire anybody's card.
      if (result.reason) {
        await forgetMissingPaymentMethod(user.id, result.reason).catch(() => {
          /* best-effort */
        });
      }
      continue;
    }
    if (result.kind !== "declined") continue; // transient / 3-D Secure: try again later, silently

    // A declined top-up must NOT touch any server's dunning state — nothing is
    // overdue, the customer simply asked us to keep a float. Tell them once a day
    // and leave it there.
    const already = await db.notification.findFirst({
      where: {
        userId: user.id,
        title: { contains: "Automatic top-up" },
        createdAt: { gt: new Date(now.getTime() - DAY) },
      },
    });
    if (!already) {
      await notify(
        user.id,
        "Automatic top-up declined",
        `We couldn't charge ${fmtUsd(amount)} to your saved card for an automatic wallet top-up. Your services are unaffected — update your card when you get a moment.`,
        "/dashboard/billing",
      );
    }
  }
}

