import { headers } from "next/headers";
import { db } from "./db";
import { impersonating } from "./auth";
import { clientIp, UNKNOWN_IP } from "./rate-limit";

/**
 * The single shared audit-log writer. Extracted verbatim (same body, same
 * impersonation-attribution logic) from what was a private, unexported
 * `audit()` in lib/actions.ts used by only ~19 call sites in that one file —
 * every other lib/actions-*.ts module wrote `db.auditLog.create(...)` ad hoc,
 * so coverage of "what did staff actually do" was inconsistent by
 * construction. New staff-reachable modules (lib/actions-work.ts,
 * lib/actions-staff.ts's grant/IP changes) call this directly so an
 * EMPLOYEE's activity is captured with the same discipline as everything
 * else, from day one.
 *
 * 2026-10-01 (docs/AUDIT-7D-2026-10-01.md F-15): `AuditLog.ip` exists in the
 * schema but nothing ever populated it — every one of the 24
 * `admin.impersonate_start` and 10 `admin.renew_now` rows in the last 7 days
 * had `ip = NULL`, so a hijacked staff session could not be told apart from
 * the real admin after the fact. The writer now records the proxy-validated
 * client IP (the same `clientIp()` the login throttle trusts) whenever it runs
 * inside a request. `headers()` throws outside a request scope (worker,
 * scripts, tests) — that is swallowed and the row is written without an IP,
 * exactly as before, so no caller's behaviour changes.
 */
export async function recordAudit(userId: string | null, action: string, detail?: string): Promise<void> {
  // Attribute to the real admin when an admin is impersonating, so customer-scoped
  // actions taken during impersonation aren't logged as if the customer did them.
  const imp = await impersonating();
  const actor = imp ? `actingAdmin=${imp.admin.id}` : "";
  const fullDetail = detail && actor ? `${detail} ${actor}` : detail || actor || undefined;
  const ip = await requestIp();
  await db.auditLog.create({ data: { userId, action, detail: fullDetail, ...(ip ? { ip } : {}) } });
}

/** The caller's validated IP when inside a request; null anywhere else. */
async function requestIp(): Promise<string | null> {
  try {
    const ip = clientIp(await headers());
    return ip === UNKNOWN_IP ? null : ip;
  } catch {
    return null;
  }
}
