/**
 * Lightweight error logging with a durable admin-visible sink.
 *
 * Every error in the platform funnels through here. `logEvent` / `logError`:
 *   1. write a structured line to stderr (captured by journald),
 *   2. if NXEON_ERROR_WEBHOOK is set, POST a compact alert (best-effort), and
 *   3. PERSIST a deduplicated row to `ErrorLog` so admins can see failures in the
 *      /admin/logs → Errors tab instead of them vanishing into stderr.
 *
 * This is the single choke point: add capture here once and every existing and
 * future `logError(...)` call is recorded automatically.
 *
 * NON-NEGOTIABLE: this module is a logger. It must NEVER throw and must NEVER
 * recurse on its own failure. Persistence and the webhook are both wrapped so a
 * DB hiccup or a bad row can never break the caller — if the DB write itself
 * fails we fall back to `console.error`, never to `logError` again.
 */
import { createHash } from "node:crypto";
import { db } from "@/lib/db";

type Level = "error" | "warn" | "info";
type Source = "worker" | "action" | "api" | "client" | "job";

/**
 * Normalize a message down to its stable shape so the same error dedups no
 * matter which id/timestamp/token it carried this time. Volatile substrings are
 * collapsed to placeholders BEFORE hashing: two "restore failed for server
 * cktr…" lines are the same incident and must share a fingerprint.
 *
 * Order matters: UUID → cuid → long hex → ISO timestamp → bare number, so a
 * broader pattern never eats a narrower one before it can match.
 */
export function normalizeForFingerprint(message: string): string {
  return String(message ?? "")
    // UUIDs (contain digits+hyphens; must run before the number pass)
    .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, "<uuid>")
    // cuid-style ids (c + 20+ alnum) — Prisma's default @id shape
    .replace(/\bc[a-z0-9]{20,}\b/gi, "<id>")
    // long hex blobs: tokens, hashes, object ids
    .replace(/\b[0-9a-f]{16,}\b/gi, "<hex>")

    // The sink itself failed. Do NOT re-enter logError (infinite recursion) — a
    // single stderr line is the floor we can always guarantee.
    console.error(`[nxeon] error-log persist failed: ${String((err as Error)?.message ?? err)}`);
  }
}

export async function logEvent(
  level: Level,
  context: string,
  detail: Record<string, unknown> = {},
): Promise<void> {
  const line = {
    ts: new Date().toISOString(),
    level,
    context,
    ...detail,
    env: process.env.NXEON_ENV ?? "production",
  };
  const serialized = JSON.stringify(line);
  if (level === "error") console.error(`[nxeon] ${serialized}`);
  else if (level === "warn") console.warn(`[nxeon] ${serialized}`);
  else console.log(`[nxeon] ${serialized}`);

  // Durable admin-visible sink. Awaited but self-contained: `persist` swallows
  // every failure, so this can neither throw nor stall the caller on a DB error.
  await persist(level, context, line as Record<string, unknown>);

  const webhook = process.env.NXEON_ERROR_WEBHOOK;
  if (webhook && level === "error") {
    // Fire-and-forget: never make a request wait on (or fail from) the outbound
    // alert. The caller does not await the fetch — only the stderr line above is
    // synchronous. Errors are swallowed so logging can never throw.
    void fetch(webhook, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ text: `🚨 Nxeon ${context}: ${detail.message ?? "error"}`, detail: line }),
      signal: AbortSignal.timeout(3000),
    }).catch(() => {});
  }
}

export function logError(context: string, error: unknown, extra: Record<string, unknown> = {}) {
  const e = error as { message?: string; stack?: string; digest?: string };
  return logEvent("error", context, {
    message: e?.message ?? String(error),
    stack: e?.stack?.split("\n").slice(0, 6).join("\n"),
    digest: e?.digest,
    ...extra,
  });
}
