// Plain server module. Everything below is pure arithmetic on the columns the worker
import { appUrl } from "./email-render";
import type Stripe from "stripe";

const AUTH_FAILURE_CODE = "payment_intent_authentication_failure";

export async function handleFailedPaymentIntent(pi: Stripe.PaymentIntent): Promise<void> {
  if (!stripeConfigured()) return;
  if (pi.last_payment_error?.code !== AUTH_FAILURE_CODE) return;

  // Dedupe against Stripe webhook redelivery: the payment intent id is unique
  // per failed attempt, embedded directly in the EmailLog `template` tag
  // (a free-form string once `html` is supplied directly — see sendMail) so
  // no schema change is needed for a per-attempt dedupe key.
  const dedupeTag = `checkout_payment_retry:${pi.id}`;
  const already = await db.emailLog.findFirst({ where: { template: dedupeTag } });
  if (already) return;

  // Find the Checkout Session this payment intent belongs to — that's where
  // OUR metadata (nxeonUserId, order type, etc.) lives; the payment intent
  // itself was never given a copy, and finding it here means every one of
  // the six-plus createXCheckout functions needed zero changes for this.
  const sessions = await stripe().checkout.sessions.list({ payment_intent: pi.id, limit: 1 });
  const session = sessions.data[0];
  const userId = session?.metadata?.nxeonUserId;
  if (!session || !userId) return; // not a Nxeon checkout (or an old session predating this field)

  const user = await db.user.findUnique({
    where: { id: userId },
    select: { email: true, name: true, emailVerifiedAt: true },
  });
  if (!user?.email || !user.emailVerifiedAt) return;

  // This is transactional (the customer's own in-flight purchase), not
  // marketing — `payment_action_required` is CRITICAL in lib/prefs.ts's
  // NOTIFY_KINDS (never suppressible), which is the correct tier here. Still
  // routed through mayDeliverTo for the (rare, non-suppressible-kind) case of
  // a hard bounce/complaint suppression, same as every other send.
  let deliverable = true;
  try {
    deliverable = await mayDeliverTo(userId, "payment_action_required", "email");
  } catch {
    deliverable = true; // fail open — mirrors mayDeliverTo's own contract
  }
  if (!deliverable) return;

  // Only offer a real retry link if the session can still be paid; otherwise
  // send them to the generic deploy page rather than a dead/expired link.
  let retryUrl = `${appUrl()}/dashboard/deploy`;
  if (session.status === "open") {
    const fallback = await createHostedFallbackFromSession(session.id).catch(() => null);
    if (fallback) retryUrl = fallback.url;
  }

  const built = emails.checkoutPaymentRetry({ name: user.name, retryUrl });
  await sendMail({
    to: user.email,
    subject: built.subject,
    html: built.html,
    template: dedupeTag,
    userId,
    kind: "payment_action_required",
  });
}

