export async function POST(req: NextRequest) {
  if (!coinbaseConfigured()) {
    return NextResponse.json({ error: "not configured" }, { status: 400 });
  }
  const raw = await req.text();
  const sig = req.headers.get("x-cc-webhook-signature");

  const verified = await verifyCoinbaseWebhookSignature(raw, sig);
  if (!verified) {
    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
  }

  let event: {
    type?: string;
    data?: { code?: string; metadata?: { nxeonPendingId?: string } };
  };
  try {
    event = JSON.parse(raw);
  } catch {
    return NextResponse.json({ error: "invalid payload" }, { status: 400 });
  }

  if (event.type === "charge:confirmed") {
    const chargeCode = event.data?.code;
    const pendingId = event.data?.metadata?.nxeonPendingId;
    if (!chargeCode || !pendingId) {
      console.error("[coinbase-webhook] confirmed event missing code/pendingId", event.data?.code);
      return NextResponse.json({ received: true });
    }
    try {
      const row = await db.pendingExternalPayment.findUnique({ where: { id: pendingId } });
      if (!row) {
        console.error("[coinbase-webhook] no PendingExternalPayment for", pendingId);
        return NextResponse.json({ received: true });
      }
      await fulfilExternalPayment({ provider: "coinbase", externalId: chargeCode, pendingId, base: process.env.APP_URL ?? "" });
    } catch (e) {
      console.error("[coinbase-webhook] fulfil failed", chargeCode, e);
    }
  }

  return NextResponse.json({ received: true });
}
/**
 * Atomically debit a wallet inside a transaction. The conditional updateMany
 * (balanceCents >= cents) prevents the read-check-then-decrement race that could
 * otherwise drive balances negative under concurrent spend. Throws
 * InsufficientBalanceError (rolling back the tx) if funds are insufficient.
 */
export async function debitWallet(
  tx: Prisma.TransactionClient,
  userId: string,
  cents: number
): Promise<void> {
  if (cents <= 0) return;
  const res = await tx.user.updateMany({
    where: { id: userId, balanceCents: { gte: cents } },
    data: { balanceCents: { decrement: cents } },
  });
  if (res.count === 0) throw new InsufficientBalanceError();
}
export async function settleOutstanding(
  serverId: string,
): Promise<{ checkout?: EmbeddedCheckout; error?: string; covered?: boolean; amountCents?: number }> {
  const user = await requireUser();
  if (!stripeConfigured()) {
    return { error: "Card payments aren't configured — add funds to your wallet instead." };
  }
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { plan: true, gamePlan: true, dedicatedIp: true, user: true },
  });
  if (!server) return { error: "Server not found." };
  if (server.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden" };
  if (server.isFree || !server.expiresAt) return { error: "This server has nothing outstanding." };

  const owner = server.user;
  const charge = renewalCharge(server, {
    ipMonthlyCents: await dedicatedIpMonthlyCents(),
    extraDiskPerGbCents: await extraDiskPerGbCents(),
    backupPlusCents: await backupPlusMonthlyCents(),
    annualDiscountPct: await annualDiscountPct(),
    taxRatePercent: (await taxContextForUser(owner)).ratePercent,
  });
  const split = walletSplit({
    dueCents: charge.totalCents,
    balanceCents: owner.balanceCents,
    useWallet: true,
  });
  if (split.cardCents === 0) {
    return {
      covered: true,
      error:
        server.userId === user.id
          ? "Your wallet already covers this renewal — it completes automatically within a few minutes."
          : "This customer's wallet already covers the renewal — it completes automatically within a few minutes.",
    };
  }

  const checkout = await createOutstandingEmbedded({
    user: owner,
    amountCents: split.cardCents,
    hostname: server.hostname,
    serverId: server.id,
  });
  if (!checkout) return { error: "We couldn't start checkout just now. Please try again in a moment." };
  return { checkout, amountCents: split.cardCents };
